private static final class Crossbow extends Base {
    Crossbow(TemplateMob mob){super(mob);}
    public boolean allows(int id){return id==ArmySkills.VOLLEY||id==ArmySkills.ROLL;}
    public boolean canStart(int id,LivingEntity target){
        if(id!=ArmySkills.VOLLEY||formationShield(level().getGameTime())==null)return true;
        // Stagger the two soldiers' windups, not their clocks or the player's movement.
        // Scan membership every20 ticks; inspect at most eight cached loaded UUIDs.
        for(UUID idOfAlly:crossbows){var ally=mob.resolve(idOfAlly);
            if(ally instanceof TemplateMob other&&other!=mob&&other.getTarget()==target&&other.skillId()==ArmySkills.VOLLEY&&other.actionAge(0)<7)return false;}
        return true;
    }
    public int choose(LivingEntity target,long now){return mob.distanceToSqr(target)<16&&mob.attack().ready(ArmySkills.ROLL,now)?ArmySkills.ROLL:ArmySkills.VOLLEY;}
    public void impact(SkillDefinition skill,int frame){
        if(skill.id()==ArmySkills.VOLLEY){var enemy=victim();if(mob.validEnemy(enemy)&&mob.distanceToSqr(enemy)<=576&&mob.hasLineOfSight(enemy)){
            TemplateProjectile.shootArmy(mob,enemy,false);mob.playSound(SoundEvents.CROSSBOW_SHOOT,.65F,.85F);}}
        else if(skill.impactTicks().indexOf(frame)==0){
            Vec3 back=mob.attack().direction().scale(-.27);
            if(level().noCollision(mob,mob.getBoundingBox().move(back)))mob.setDeltaMovement(back.x,.18,back.z);
        }else if(skill.impactTicks().indexOf(frame)==1)ArmyCaltrop.spawn(mob);
    }
    public void tick(long now){
        if(mob.skillId()==ArmySkills.ROLL&&mob.attack().state(now)==AttackState.ACTIVE&&mob.actionAge(0)>6&&mob.actionAge(0)<14){
            Vec3 back=mob.attack().direction().scale(-.25);
            if(level().noCollision(mob,mob.getBoundingBox().move(back)))mob.setDeltaMovement(back.x,mob.getDeltaMovement().y,back.z);
        }
    }
    public void move(LivingEntity target,long now){
        double distance=mob.distanceToSqr(target);
        if(distance<49)navigate(mob.position().add(mob.position().subtract(target.position()).multiply(1,0,1).normalize().scale(4)),1);
        else{var leader=formationShield(now);
            if(leader!=null){Vec3 spot=formationSpot(leader,target,false);if(mob.position().distanceToSqr(spot)>.5)navigate(spot,1);else mob.getNavigation().stop();}
            else if(distance>400||!mob.hasLineOfSight(target))super.move(target,now);else mob.getNavigation().stop();}

public static TemplateProjectile shootArmy(TemplateMob owner,LivingEntity victim,boolean hook) {
    var projectile=new TemplateProjectile(BlueprintEntities.TEMPLATE_PROJECTILE.get(),owner.level());
    projectile.setOwner(owner);projectile.entityData.set(ARMY_MODE,hook?2:1);
    projectile.actionEpoch=owner.skillStartTime();projectile.target=victim.getUUID();
    projectile.damage=(float)owner.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE);
    projectile.setItem(new ItemStack(hook?Items.IRON_NUGGET:Items.ARROW));
    projectile.setPos(owner.getX(),owner.getEyeY()-.3,owner.getZ());
    Vec3 aim=(hook?victim.position().add(0,.25,0):victim.getBoundingBox().getCenter()).subtract(projectile.position());
    projectile.shoot(aim.x,aim.y,aim.z,hook?1.35F:1.65F,0);
    owner.level().addFreshEntity(projectile);return projectile;
}

/** The same validation gates AI and operator/GameTest starts; no client can request a damage frame. */
public boolean startSkill(int id, LivingEntity target) {
    if (level().isClientSide || !isAlive() || isRemoved() || !allows(id)) return false;
    SkillDefinition base = TemplateSkills.byId(id);
    if (base == null || (id == ArmySkills.SCORPION_EMERGE && target == this ? false : id == TemplateSkills.POSSESSION ? !validSupport(target) : !validEnemy(target))) return false;
    double range = distanceTo(target);
    if (range < base.minRange() || range > (id == ArmySkills.AXE_COUNTER ? 40 : base.maxRange()) || id != ArmySkills.SCORPION_EMERGE && base.requiresSight() && !hasLineOfSight(target)) return false;
    if (id == TemplateSkills.ROCK_THROW && !onHighGround(target)) return false;
    if (army != null && !army.canStart(id,target)) return false;
    Vec3 direction = target.position().subtract(position()).multiply(1, 0, 1).normalize();
    if (direction.lengthSqr() < .0001) direction = getLookAngle().multiply(1, 0, 1).normalize();
    // A fuse uses real elapsed time, not attack speed: three consecutive close seconds.
    float speed = id != ArmySkills.DETONATE && id != ArmySkills.AXE_COUNTER && id != ArmySkills.CHILD_CURSE && id != ArmySkills.SKULL_DIVE && id != ArmySkills.SKULL_BLOOD && id != ArmySkills.TOAD_LEAP && id != ArmySkills.SERPENT_COIL && id != ArmySkills.SERPENT_BITE && id != ArmySkills.STONE_SLAM && id != ArmySkills.STONE_UPPERCUT && id != ArmySkills.DOG_BITE && id != ArmySkills.DOG_ALARM && kind != Kind.BRONZE_SNAKE && kind != Kind.MINING_SPIDER && kind != Kind.LANTERN_BAT && kind != Kind.BLIND_FISH && kind != Kind.DROWNER && kind != Kind.BIXI && kind != Kind.CENTIPEDE && kind != Kind.YECHA && kind != Kind.PALANQUIN && hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()) ? 1.3F : 1F;
    SkillDefinition effective = TemplateSkills.accelerated(base, speed);
    if (!attack.tryStart(effective, level().getGameTime(), position(), direction, target.getUUID())) return false;
    if(army!=null)army.started(id,target);
    entityData.set(SPEED, speed);
    coverUntil = 0;
    entityData.set(SKILL, id); entityData.set(START, attack.started()); entityData.set(PHASE, AttackState.WINDUP.ordinal());
    navigation.stop(); face(direction);
    if (id == TemplateSkills.POSSESSION) entityData.set(BUFF_TARGET, target.getId());
    if (id == TemplateSkills.POUNCE) {
        Vec3 towards = target.position().subtract(position()).multiply(1, 0, 1);
        leapDestination = position().add(towards.normalize().scale(Math.min(5.6, towards.length())));
    }
    BlueprintVisualEvent.start(this, effective, attack.origin(), attack.direction(), target.getId());
    playSound(kind == Kind.BEAST ? SoundEvents.FOX_AGGRO : kind == Kind.PRIEST ? SoundEvents.EVOKER_PREPARE_ATTACK : SoundEvents.PLAYER_ATTACK_SWEEP,
            .6F, kind == Kind.SHIELD ? .65F : 1F);
    return true;
}
private boolean allows(int id) {
    return switch (kind) {
        case SWORD -> id == TemplateSkills.SWORD_COMBO;
        case SHIELD -> id == TemplateSkills.SHIELD_COMBO;
        case PRIEST -> id == TemplateSkills.TALISMAN_VOLLEY || id == TemplateSkills.POSSESSION;
        case BEAST -> id == TemplateSkills.POUNCE || id == TemplateSkills.ROCK_THROW;
        default -> army != null && army.allows(id);
    };
}

if (now >= nextTacticalScan) { nextTacticalScan = now + 20; updateTactics(now); }
if (possessedUntil > 0) {
    LivingEntity source = resolve(possessor);
    // An unloaded ally could not receive releaseSupport when its priest died or
    // changed links. Reconcile once both are loaded; a missing UUID alone is not death.
    if (now >= possessedUntil || source != null && (!source.isAlive()
            || source instanceof TemplateMob priest && (!getUUID().equals(priest.possessedAlly)
                    || !priest.validSupport(this))))
        clearPossession();
}
entityData.set(POSSESSED, hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()));
LivingEntity linked = resolve(possessedAlly);
if (linkUntil > 0 && (now >= linkUntil || linked != null && !validSupport(linked))) releaseSupport();
if (linked != null && linkUntil > now) entityData.set(BUFF_TARGET, linked.getId());
if (attack.current() != null) {
    face(attack.direction());
    navigation.stop();
    if (skillId() != TemplateSkills.POUNCE && skillId() != ArmySkills.ROLL && skillId() != ArmySkills.GRAPPLE && skillId() != ArmySkills.SKULL_DIVE && skillId() != ArmySkills.BAT_DIVE && skillId() != ArmySkills.YECHA_GRAB && skillId() != ArmySkills.TOAD_LEAP)
        setDeltaMovement(getDeltaMovement().multiply(.35, 1, .35));
    attack.advance(now, this::impact);
    // Damage callbacks (e.g. thorns) may synchronously enter die(). Do not erase its
    // authoritative death clock or cancel the death visual that die() has just sent.
    if (!isAlive()) return;
    if (attack.current() == null && skillId() != 0) finishAction();
}
entityData.set(PHASE, attack.state(now).ordinal());
