            double lift=moving?Math.max(0,Math.sin(phase))*1.6:0;
            double dx=8,dy=Mth.clamp(s.scorpionFloor[i]*16+.5+lift-7,-9,1);
            double a=Math.sqrt(34),b=Math.sqrt(21.25),r=Mth.clamp(Math.hypot(dx,dy),Math.abs(a-b)+.01,a+b-.01);
